import { useState, type FormEvent } from 'react';
import { JxAlert, JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const isValid = EMAIL_PATTERN.test(email);
  const errorText = email.length > 0 && !isValid ? 'Похоже, это не адрес почты' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) return;
    setInvited(email);
    setEmail('');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      {invited && (
        <JxAlert intent="success" title="Приглашение отправлено">
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: '8px' }}>
            <span>Мы написали на {invited}.</span>
            <JxButton variant="ghost" size="sm" onClick={() => setInvited(null)}>
              Закрыть
            </JxButton>
          </div>
        </JxAlert>
      )}

      <form onSubmit={submit} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        <JxInputField
          label="Почта"
          type="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          helperText="Приглашение придёт на этот адрес"
          errorText={errorText}
        />

        <JxSelect
          label="Роль"
          options={[
            { value: 'member', label: 'Участник', meta: 'Работа с задачами' },
            { value: 'editor', label: 'Редактор', meta: 'Правка содержимого' },
            { value: 'admin', label: 'Администратор', meta: 'Полный доступ' },
          ]}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!isValid}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

